import { Mesh, PlaneGeometry, Group, Object3D, Vector3 } from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  uv,
  mix,
  color,
  float,
  add,
  sub,
  mul,
  vec2,
  vec3,
  vec4
} from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { createMSDFMesh } from '@/text';

export default function createNode(config, ctx) {
  // ---------- Panel ----------
  const panelWidth = 3.4;
  const panelHeight = 1.9;
  const panelGeom = new PlaneGeometry(panelWidth, panelHeight);
  const panelMat = new MeshStandardNodeMaterial();
  // vertical engineered gradient
  panelMat.baseColorNode = mix(
    color('#1a1a22'),
    color('#111116'),
    uv().y
  );
  panelMat.roughness = 0.6;
  panelMat.metalness = 0.2;
  panelMat.clearcoat = 0.1;
  panelMat.clearcoatRoughness = 0.0;
  panelMat.transparent = true;
  panelMat.opacity = 0.0; // start invisible for fade‑up

  const panelMesh = new Mesh(panelGeom, panelMat);
  panelMesh.position.set(0, 0, 0);
  panelMesh.castShadow = true;
  panelMesh.receiveShadow = true;

  // ---------- Text Elements ----------
  const padding = 0.5; // base‑unit * 2
  const quoteMarkSize = 0.62; // scene‑unit height
  const quoteMarkDepth = 0.04;
  const quoteOffsetY = 0.25; // baseline grid step
  const ruleHeight = 0.02;
  const ruleWidth = 0.2;
  const ruleEmissive = 1.4;

  // Quote Mark
  const quoteMark = createMSDFMesh({
    text: '“',
    fontFamily: 'Lora',
    fontWeight: 600,
    fontSize: 62,
    color: '#ff2a38',
    letterSpacing: 0,
    lineHeight: 1,
    // we force a target height; width will follow glyph aspect
    targetHeight: quoteMarkSize,
    depth: quoteMarkDepth,
    // anchor is top‑left relative to its own bbox
    anchor: 'top-left'
  });
  quoteMark.position.set(
    -panelWidth / 2 + padding + quoteMarkSize / 2,
    panelHeight / 2 - padding - quoteMarkSize / 2,
    quoteMarkDepth / 2
  );
  quoteMark.scale.set(1, 1, 1);
  // start scaled for weighted‑settle
  quoteMark.scale.set(1.04, 1.04, 1.04);

  // Quote Text
  const quoteText = createMSDFMesh({
    text:
      'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.',
    fontFamily: 'Lora',
    fontWeight: 400,
    fontSize: 20,
    color: '#e8ecf2',
    letterSpacing: 0,
    lineHeight: 1.45,
    maxWidth: 2.4,
    // anchor top‑left for easier positioning
    anchor: 'top-left',
    // slight Z offset for raking light
    depth: 0.03
  });
  // Position: below quote mark, respecting baseline grid
  quoteText.position.set(
    -panelWidth / 2 + padding,
    panelHeight / 2 -
      padding -
      quoteMarkSize -
      quoteOffsetY -
      quoteText.userData.computedHeight / 2,
    0.03
  );

  // Attribution Line (with rule)
  const attribution = createMSDFMesh({
    text: 'M. OKAFOR',
    fontFamily: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 13,
    color: '#e8ecf2',
    letterSpacing: 0.08,
    lineHeight: 1.2,
    anchor: 'top-left'
  });
  const caption = createMSDFMesh({
    text: 'COLLECTOR SINCE 2019',
    fontFamily: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 9,
    color: '#e8ecf2',
    letterSpacing: 0.12,
    lineHeight: 1.4,
    anchor: 'top-left'
  });

  // Rule (accent line)
  const ruleGeom = new PlaneGeometry(ruleWidth, ruleHeight);
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.colorNode = color('#ff2a38');
  ruleMat.emissiveNode = mul(color('#ff2a38'), float(ruleEmissive));
  const ruleMesh = new Mesh(ruleGeom, ruleMat);
  // Position rule left of attribution
  ruleMesh.position.set(
    -panelWidth / 2 + padding,
    attribution.position.y - attribution.userData.computedHeight / 2 - 0.25,
    0
  );

  // Position attribution next to rule
  attribution.position.set(
    ruleMesh.position.x + ruleWidth / 2 + 0.05,
    ruleMesh.position.y,
    0
  );

  // Position caption below attribution
  caption.position.set(
    attribution.position.x,
    attribution.position.y - attribution.userData.computedHeight / 2 - 0.1,
    0
  );

  // ---------- Group ----------
  const root = new Group();
  root.add(panelMesh);
  root.add(quoteMark);
  root.add(quoteText);
  root.add(ruleMesh);
  root.add(attribution);
  root.add(caption);

  // Apply scene placement
  if (config.position) root.position.fromArray(config.position);
  if (config.rotation) root.rotation.fromArray(config.rotation);
  if (config.scale) root.scale.fromArray(config.scale);

  // ---------- Animations ----------
  const masterTimeline = gsap.timeline();

  // Panel fade‑up
  masterTimeline.fromTo(
    panelMat,
    { opacity: 0, transparent: true },
    {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    },
    0
  );
  masterTimeline.fromTo(
    root.position,
    { y: 0.2 },
    { y: 0, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    0
  );

  // Quote mark weighted‑settle
  masterTimeline.to(
    quoteMark.scale,
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)'
    },
    0
  );

  // ---------- Cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    masterTimeline.kill();
    panelMat.dispose();
    ruleMat.dispose();
    // dispose any textures generated by createMSDFMesh if they expose a dispose method
    [
      quoteMark,
      quoteText,
      attribution,
      caption
    ].forEach((obj) => {
      if (obj.material && obj.material.map && obj.material.map.dispose) {
        obj.material.map.dispose();
      }
      if (obj.material) obj.material.dispose();
    });
  };

  // ---------- Primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  return root;
}
